<script setup lang="ts">
import type { PublicDownloadProjection, PublicPricingProjection, PublicProjectionLoadState } from "~/utils/public-projection";

const props = defineProps<{
  kind: "pricing" | "download";
  state: PublicProjectionLoadState;
  empty: boolean;
  updatedAt: string | null;
  plans: readonly PublicPricingProjection[];
  channels: readonly PublicDownloadProjection[];
}>();
const emit = defineEmits<{ retry: [] }>();
const { t, locale } = useSiteText();
const { officialI18n } = useNuxtApp().$foundation;
const desktop = computed(() => props.kind === "pricing" ? "pricing-desktop-168-1956" : "download-desktop-168-2171");
const mobile = computed(() => props.kind === "pricing" ? "pricing-mobile-168-2091" : "download-mobile-168-2311");
const key = (name: string) => `official.v1.experience.${props.kind}.${name}`;
const asset = (context: string, name: string) => `/figma-v1/assets/${context}/${name}.svg`;
const hasCatalog = computed(() => props.state === "ready" && !props.empty);
const displayState = computed(() => props.empty ? "empty" : props.state);
const updatedAt = computed(() => props.updatedAt
  ? officialI18n.formatDate(props.updatedAt, { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Shanghai" }, locale.value)
  : "");
const cardLinks = ["/help", "/announcements", "/start"];
function billingLabel(item: PublicPricingProjection) {
  const value = item.billingPeriod || item.unit;
  return ["FREE", "MONTH", "QUARTER", "YEAR", "PERPETUAL"].includes(value)
    ? t(`official.v1.experience.catalog.billing.${value}`)
    : value || item.currency;
}
</script>

